def is_stuck(events, now, grace):
    # map job_id -> list of events
    job_events = {}
    for ev in events:
        job_events.setdefault(ev['job_id'], []).append(ev)
    stuck_ids = []
    for job_id, lst in job_events.items():
        # find latest event (max at)
        latest = max(lst, key=lambda ev: ev['at'])
        if latest['state'] == 'running':
            # check older than grace seconds: at < now - grace
            if latest['at'] < now - grace:
                stuck_ids.append(job_id)
    stuck_ids.sort()
    return stuck_ids
